import 'package:blockchain_utils/blockchain_utils.dart';
import 'package:on_chain/algorand/src/address/address.dart';
import 'package:on_chain/algorand/src/transaction/src/transaction.dart';
import 'package:test/test.dart';

import '../../utils.dart';
void serializationTransactionTest() {
  group('Algorand/Transaction Serialization', _test);
}

void main() {
  OnChainUtilsTestApi.runTest(serializationTransactionTest, "Transaction");
}


void _test() {
  test('pay', () {
    final data = BytesUtils.fromHexString(
      "88a3616d7401a3666565cd03e8a26676cd2710a26768c420c061c4d8fc1dbdded2d7604be4568e3f6d041987ac37bde4b620b5ab39248adfa26c76cd2af8a3726376c42031d93ef06e1f74cea0d8b7743574d9743dc63953a4082fc23e6beb1d0577fb47a3736e64c420bcfafbb3c9ea2d5b188e0ae8fb158907597ae7100ef1025fbd67e44694e265b0a474797065a3706179",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('hb', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('hb', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('stpf', () {
    final data = BytesUtils.fromHexString(
      "84a26676cd2710a26768c420c061c4d8fc1dbdded2d7604be4568e3f6d041987ac37bde4b620b5ab39248adfa26c76cd2af8a474797065a473747066",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('appl', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('afrz', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
  test('axfer', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
    expect(
      transaction.assetReceiver,
      AlgoAddress("GHMT54DOD52M5IGYW52DK5GZOQ64MOKTUQEC7QR6NPVR2BLX7NDZN53EJM"),
    );
  });
  test('acfg', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
    expect(transaction.assetParams?.url, "https://example.com");
    expect(transaction.assetParams?.assetName, "Test Asset");
    expect(transaction.assetParams?.decimals, BigInt.from(2));
  });
  test('keyreg', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
    expect(transaction.votePk, isNotNull);
    expect(transaction.voteLast, BigInt.from(20000));
  });
  test('payment', () {
    final data = BytesUtils.fromHexString(
      "",
    );
    final transaction = AlgoTransaction.deserialize(data);
    final encode = transaction.toSerializeBytes();
    expect(encode, data);
  });
}
